# ef-helper: runtime support for build.sh files generated by emforge-export.
#
# Subcommands (all paths absolute):
#   fetch-url    download (cache + verify) and unpack a url source
#   fetch-git    clone a git source
#   copy-path    copy a path source from the recipe directory
#   patch        apply a patch with strip-level detection
#   snapshot     record the files of a prefix
#   collect      package the new files of a prefix
#   install      install a stored package into a prefix (with relocation)
#   subst        replace @@EF:VAR@@ tokens with environment values
#   test-contents  run a package_contents test
#   spec-match   check a version against a conda version spec
#   envsubst     minimal gettext envsubst replacement (shim)
#   conda-pkg    write a conda .tar.bz2 for a stored package
#   repodata     write repodata.json for a directory of conda packages
#   unit-env     print shell exports for env_vars.d json files
import hashlib
import json
import os
import re
import shutil
import stat
import subprocess
import sys
import tarfile
import tempfile
import urllib.request
import zipfile

# ----------------------------------------------------------------------------
# matchspec (embedded copy)
# ----------------------------------------------------------------------------
#@@MATCHSPEC@@


def log(msg):
    sys.stderr.write("[ef] %s\n" % msg)
    sys.stderr.flush()


def die(msg, code=1):
    sys.stderr.write("[ef] ERROR: %s\n" % msg)
    sys.exit(code)


def sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def md5_file(path):
    h = hashlib.md5()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


# ----------------------------------------------------------------------------
# archives
# ----------------------------------------------------------------------------
TARBALL_EXT = (".tar.gz", ".tgz", ".taz", ".tar.bz2", ".tbz", ".tbz2", ".tz2",
               ".tar.lzma", ".tlz", ".tar.xz", ".txz", ".tar.zst", ".tzst",
               ".tar.Z", ".taZ", ".tar.lz", ".tar.lzo", ".tar")


def is_archive_name(name):
    return name.endswith(TARBALL_EXT) or name.endswith(".zip") or name.endswith(".7z")


def _safe_members(tf, dest):
    dest = os.path.realpath(dest)
    for m in tf.getmembers():
        p = os.path.realpath(os.path.join(dest, m.name))
        if not (p == dest or p.startswith(dest + os.sep)):
            die("archive member escapes destination: %s" % m.name)
        yield m


def extract_archive(path, name, dest):
    os.makedirs(dest, exist_ok=True)
    if name.endswith(".zip"):
        with zipfile.ZipFile(path) as zf:
            for info in zf.infolist():
                target = os.path.realpath(os.path.join(dest, info.filename))
                if not target.startswith(os.path.realpath(dest)):
                    die("zip member escapes destination: %s" % info.filename)
            zf.extractall(dest)
            # restore unix permissions
            for info in zf.infolist():
                mode = (info.external_attr >> 16) & 0o777
                if mode:
                    try:
                        os.chmod(os.path.join(dest, info.filename), mode)
                    except OSError:
                        pass
        return
    if name.endswith(".7z"):
        exe = shutil.which("7z") or shutil.which("7za") or shutil.which("7zz")
        if not exe:
            die("7z archive %s needs the 7z tool" % name)
        subprocess.check_call([exe, "x", "-y", "-o" + dest, path], stdout=subprocess.DEVNULL)
        return
    if name.endswith((".tar.zst", ".tzst", ".tar.lz", ".tar.lzo", ".tar.Z", ".taZ")):
        subprocess.check_call(["tar", "-xf", path, "-C", dest])
        return
    try:
        with tarfile.open(path) as tf:
            if hasattr(tarfile, "data_filter"):
                tf.extractall(dest, members=_safe_members(tf, dest), filter="tar")
            else:
                tf.extractall(dest, members=_safe_members(tf, dest))
    except tarfile.ReadError:
        subprocess.check_call(["tar", "-xf", path, "-C", dest])


def move_stripped(src, dest):
    """Like rattler-build: if the archive has a single top-level directory,
    move its contents (not the directory itself) into dest."""
    entries = os.listdir(src)
    root = src
    if len(entries) == 1 and os.path.isdir(os.path.join(src, entries[0])) and \
            not os.path.islink(os.path.join(src, entries[0])):
        root = os.path.join(src, entries[0])
    os.makedirs(dest, exist_ok=True)
    for e in os.listdir(root):
        s = os.path.join(root, e)
        d = os.path.join(dest, e)
        if os.path.lexists(d):
            if os.path.isdir(d) and not os.path.islink(d) and os.path.isdir(s):
                copytree(s, d)
                continue
            if os.path.isdir(d) and not os.path.islink(d):
                shutil.rmtree(d)
            else:
                os.unlink(d)
        shutil.move(s, d)


def copytree(src, dst, symlinks=True, ignore_git=False):
    os.makedirs(dst, exist_ok=True)
    for e in os.listdir(src):
        if ignore_git and e == ".git":
            continue
        s = os.path.join(src, e)
        d = os.path.join(dst, e)
        if os.path.islink(s) and symlinks:
            if os.path.lexists(d):
                os.unlink(d)
            os.symlink(os.readlink(s), d)
        elif os.path.isdir(s):
            copytree(s, d, symlinks)
        else:
            if os.path.lexists(d):
                os.unlink(d)
            shutil.copy2(s, d)


# ----------------------------------------------------------------------------
# downloads
# ----------------------------------------------------------------------------

def _download(url, out):
    tmp = out + ".part"
    curl = shutil.which("curl")
    if curl:
        # give up on a stalled transfer (< 1 kB/s for 2 minutes) so that the
        # next URL / mirror is tried
        cmd = [curl, "-fL", "--retry", "3", "--retry-delay", "2", "--connect-timeout", "30",
               "--speed-limit", "1024", "--speed-time", "120", "-o", tmp, url]
        if sys.stderr.isatty():
            cmd.insert(1, "-#")
        else:
            cmd.insert(1, "-sS")
        r = subprocess.call(cmd)
        if r != 0:
            if os.path.exists(tmp):
                os.unlink(tmp)
            return False
    else:
        wget = shutil.which("wget")
        if wget:
            r = subprocess.call([wget, "-q", "-O", tmp, url])
            if r != 0:
                if os.path.exists(tmp):
                    os.unlink(tmp)
                return False
        else:
            try:
                req = urllib.request.Request(url, headers={"User-Agent": "emforge-export"})
                with urllib.request.urlopen(req, timeout=120) as resp, open(tmp, "wb") as f:
                    shutil.copyfileobj(resp, f)
            except Exception as e:  # noqa
                log("download failed: %s (%s)" % (url, e))
                if os.path.exists(tmp):
                    os.unlink(tmp)
                return False
    os.replace(tmp, out)
    return True


_GH_ARCHIVE = re.compile(
    r"^https://github\.com/([^/]+)/([^/]+)/archive/(?:refs/(tags|heads)/)?(.+?)\.(tar\.gz|zip)$")


def _github_archive_via_git(url, out, sha256):
    """GitHub archive tarballs are `git archive --prefix=<repo>-<ref>/ | gzip -n`.
    If codeload.github.com is unreachable we can rebuild the identical
    tarball from a git clone; the sha256 check still applies."""
    m = _GH_ARCHIVE.match(url)
    if not m or m.group(5) != "tar.gz" or not shutil.which("git"):
        return False
    owner, repo, kind, ref = m.group(1), m.group(2), m.group(3), m.group(4)
    if repo.endswith(".git"):
        repo = repo[:-4]
    log("reconstructing %s from a git clone of %s/%s@%s" % (os.path.basename(url), owner, repo, ref))
    tmp = tempfile.mkdtemp(prefix="ef-gh-", dir=os.path.dirname(out))
    try:
        repo_dir = os.path.join(tmp, "repo")
        git_url = "https://github.com/%s/%s.git" % (owner, repo)
        if re.fullmatch(r"[0-9a-f]{40}", ref):
            subprocess.check_call(["git", "init", "-q", repo_dir])
            subprocess.check_call(["git", "-C", repo_dir, "fetch", "-q", "--depth", "1", git_url, ref])
            rev = "FETCH_HEAD"
        else:
            r = subprocess.call(["git", "clone", "-q", "--depth", "1", "--branch", ref,
                                 "--no-checkout", git_url, repo_dir])
            if r != 0:
                return False
            rev = "HEAD"
        names = []
        base = ref
        if kind == "tags" or kind is None:
            if re.match(r"^v\d", ref):
                names.append(repo + "-" + ref[1:])
        names.append(repo + "-" + base)
        names.append(repo + "-" + base.replace("/", "-"))
        for prefix in dict.fromkeys(names):
            tar_path = os.path.join(tmp, "a.tar")
            with open(tar_path, "wb") as f:
                subprocess.check_call(["git", "-C", repo_dir, "archive", "--format=tar",
                                       "--prefix=%s/" % prefix, rev], stdout=f)
            gz = os.path.join(tmp, "a.tar.gz")
            with open(gz, "wb") as f:
                subprocess.check_call(["gzip", "-cn", tar_path], stdout=f)
            if sha256 is None or sha256_file(gz) == sha256:
                shutil.move(gz, out)
                return True
        log("git-archive reconstruction did not reproduce the expected checksum")
        return False
    except subprocess.CalledProcessError as e:
        log("git fallback failed: %s" % e)
        return False
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def _verify(path, sha256, md5):
    if sha256 and sha256_file(path) != sha256.lower():
        return "sha256 mismatch (expected %s, got %s)" % (sha256, sha256_file(path))
    if md5 and md5_file(path) != md5.lower():
        return "md5 mismatch (expected %s, got %s)" % (md5, md5_file(path))
    return None


def _url_filename(url):
    tail = url.split("?", 1)[0].rstrip("/").rsplit("/", 1)[-1]
    try:
        from urllib.parse import unquote
        tail = unquote(tail)
    except Exception:  # noqa
        pass
    return tail or "download"


def obtain(urls, sha256, md5, cache, extra_caches, offline, name_hint=None):
    """Return path of a verified file for the given urls (cached by checksum)."""
    os.makedirs(cache, exist_ok=True)
    key = sha256 or md5 or hashlib.sha256("\n".join(urls).encode()).hexdigest()
    fname = name_hint or _url_filename(urls[0])
    cached = os.path.join(cache, "%s-%s" % (key[:16], fname))
    if os.path.isfile(cached) and not _verify(cached, sha256, md5):
        return cached, fname
    # user-provided caches: by file name or by checksum
    for d in extra_caches:
        if not d or not os.path.isdir(d):
            continue
        for cand in [fname] + [_url_filename(u) for u in urls] + [key, os.path.basename(cached)]:
            p = os.path.join(d, cand)
            if os.path.isfile(p) and not _verify(p, sha256, md5):
                shutil.copy2(p, cached)
                return cached, fname
    if offline:
        die("offline and %s is not in any source cache (%s)" % (fname, ", ".join(urls)))
    mirrors = [m for m in os.environ.get("EF_MIRRORS", "").split() if m]
    candidates = []
    for u in urls:
        for m in mirrors:
            # EF_MIRRORS="https://mirror.example/{sha256} https://other/{filename}"
            candidates.append(m.replace("{sha256}", key).replace("{filename}", _url_filename(u)))
        candidates.append(u)
    errors = []
    for u in candidates:
        log("downloading %s" % u)
        if not _download(u, cached):
            errors.append("%s: download failed" % u)
            continue
        err = _verify(cached, sha256, md5)
        if err:
            errors.append("%s: %s" % (u, err))
            os.unlink(cached)
            continue
        return cached, fname
    for u in urls:
        if os.environ.get("EF_NO_GIT_FALLBACK") != "1" and _github_archive_via_git(u, cached, sha256):
            err = _verify(cached, sha256, md5)
            if not err:
                return cached, fname
            os.unlink(cached)
    die("could not obtain %s:\n  %s" % (fname, "\n  ".join(errors)))


def cmd_fetch_url(a):
    # args: cache dest sha256 md5 file_name offline extra_caches urls...
    cache, dest, sha256, md5, file_name, offline, extra = a[:7]
    urls = a[7:]
    sha256 = sha256 or None
    md5 = md5 or None
    path, fname = obtain(urls, sha256, md5, cache, extra.split(":"), offline == "1")
    os.makedirs(dest, exist_ok=True)
    if not file_name and is_archive_name(fname):
        tmp = tempfile.mkdtemp(prefix=".ef-extract-", dir=dest)
        try:
            extract_archive(path, fname, tmp)
            move_stripped(tmp, dest)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)
    else:
        target = os.path.join(dest, file_name or fname)
        shutil.copy2(path, target)
    log("source %s -> %s" % (fname, dest))


def cmd_obtain(a):
    # obtain cache sha256 offline extra url... -> prints path
    cache, sha256, offline, extra = a[:4]
    path, _ = obtain(a[4:], sha256 or None, None, cache, extra.split(":"), offline == "1")
    print(path)


def _git_clone(url, tmp, revkind, rev, depth, submodules):
    """Clone <url> at a tag / branch / commit.  Without an explicit depth the
    clone is shallow (the build only needs the tree), including submodules;
    depth -1 asks for full history."""
    full = depth in ("-1",)
    shallow = None if full else (depth if depth not in ("", "None") else "1")
    sub = submodules != "false"
    if revkind == "rev" and rev:
        if shallow:
            # fetch just that commit (servers allow it for reachable commits)
            os.makedirs(tmp, exist_ok=True)
            ok = (subprocess.call(["git", "init", "-q", tmp]) == 0 and
                  subprocess.call(["git", "-C", tmp, "remote", "add", "origin", url]) == 0 and
                  subprocess.call(["git", "-C", tmp, "fetch", "-q", "--depth", shallow, "origin", rev]) == 0 and
                  subprocess.call(["git", "-C", tmp, "-c", "advice.detachedHead=false", "checkout", "-q", "FETCH_HEAD"]) == 0)
            if ok:
                if sub:
                    subprocess.check_call(["git", "-C", tmp, "submodule", "update", "-q", "--init",
                                           "--recursive", "--depth", "1"])
                return
            shutil.rmtree(tmp, ignore_errors=True)
        subprocess.check_call(["git", "-c", "advice.detachedHead=false", "clone", "-q"] + (["--recurse-submodules"] if sub else []) +
                              [url, tmp])
        if subprocess.call(["git", "-C", tmp, "checkout", "-q", rev]) != 0:
            subprocess.check_call(["git", "-C", tmp, "fetch", "-q", "origin", rev])
            subprocess.check_call(["git", "-C", tmp, "checkout", "-q", rev])
        if sub:
            subprocess.check_call(["git", "-C", tmp, "submodule", "update", "-q", "--init", "--recursive"])
        return
    cmd = ["git", "-c", "advice.detachedHead=false", "clone", "-q"]
    if shallow:
        cmd += ["--depth", shallow]
        if sub:
            cmd += ["--shallow-submodules"]
    if revkind in ("tag", "branch") and rev:
        cmd += ["--branch", rev]
    if sub:
        cmd += ["--recurse-submodules"]
    subprocess.check_call(cmd + [url, tmp])


def cmd_fetch_git(a):
    # args: cache dest url revkind rev depth submodules lfs expected_commit offline
    cache, dest, url, revkind, rev, depth, submodules, lfs, expected, offline = a[:10]
    os.makedirs(cache, exist_ok=True)
    key = hashlib.sha256(("%s#%s:%s" % (url, revkind, rev)).encode()).hexdigest()[:20]
    repo = os.path.join(cache, key)
    if not os.path.isdir(os.path.join(repo, ".git")):
        if offline == "1":
            die("offline and git source %s is not cached" % url)
        tmp = repo + ".tmp"
        shutil.rmtree(tmp, ignore_errors=True)
        log("cloning %s %s" % (url, rev or ""))
        _git_clone(url, tmp, revkind, rev, depth, submodules)
        if lfs == "true":
            subprocess.call(["git", "-C", tmp, "lfs", "pull"])
        os.replace(tmp, repo)
    head = subprocess.check_output(["git", "-C", repo, "rev-parse", "HEAD"]).decode().strip()
    if expected and expected != "None" and not head.startswith(expected):
        die("git source %s: expected commit %s, got %s" % (url, expected, head))
    copytree(repo, dest)
    log("git %s @ %s -> %s" % (url, head[:12], dest))


def cmd_copy_path(a):
    # args: src dest file_name sha256 md5 use_gitignore
    src, dest, file_name, sha256, md5 = a[:5]
    os.makedirs(dest, exist_ok=True)
    if os.path.isdir(src):
        copytree(src, dest, ignore_git=False)
        return
    fname = file_name or os.path.basename(src)
    err = _verify(src, sha256 or None, md5 or None)
    if err:
        die("path source %s: %s" % (src, err))
    if not file_name and is_archive_name(fname):
        tmp = tempfile.mkdtemp(prefix=".ef-extract-", dir=dest)
        try:
            extract_archive(src, fname, tmp)
            move_stripped(tmp, dest)
        finally:
            shutil.rmtree(tmp, ignore_errors=True)
    else:
        shutil.copy2(src, os.path.join(dest, fname))


# ----------------------------------------------------------------------------
# patches (strip level detection like rattler-build)
# ----------------------------------------------------------------------------

def _patch_paths(text):
    files = []
    cur_old = None
    for line in text.splitlines():
        if line.startswith("--- "):
            cur_old = line[4:].split("\t")[0].strip()
            if cur_old.startswith('"') and cur_old.endswith('"'):
                cur_old = cur_old[1:-1]
        elif line.startswith("+++ ") and cur_old is not None:
            new = line[4:].split("\t")[0].strip()
            if new.startswith('"') and new.endswith('"'):
                new = new[1:-1]
            files.append((cur_old, new))
            cur_old = None
    return files


def guess_strip(patch_file, work_dir):
    text = open(patch_file, "rb").read().decode("utf-8", "replace")
    pairs = _patch_paths(text)
    existing = set()
    for old, new in pairs:
        if old != "/dev/null":
            existing.add(old)
            if new != "/dev/null":
                existing.add(new)
    if existing:
        maxc = max(len([c for c in p.split("/") if c]) for p in existing)
        for level in range(0, maxc):
            for p in existing:
                comps = [c for c in p.split("/") if c]
                rest = "/".join(comps[level:])
                if rest and os.path.exists(os.path.join(work_dir, rest)):
                    return level
    for old, new in pairs:
        for p in (old, new):
            first = p.split("/")[0]
            if first in ("a", "b"):
                return 1
    return 0


def cmd_patch(a):
    work_dir, patch_file = a[0], a[1]
    if not os.path.isfile(patch_file):
        die("patch not found: %s" % patch_file)
    level = guess_strip(patch_file, work_dir)
    log("applying %s (-p%d)" % (os.path.basename(patch_file), level))
    patch_exe = os.environ.get("EF_PATCH") or shutil.which("patch") or shutil.which("gpatch")
    if patch_exe:
        r = subprocess.run([patch_exe, "-p%d" % level, "--no-backup-if-mismatch", "-i",
                            patch_file, "-d", work_dir], stdout=subprocess.PIPE,
                           stderr=subprocess.STDOUT)
        if r.returncode == 0:
            return
        out = r.stdout.decode("utf-8", "replace")
    else:
        out = "no patch executable"
    if shutil.which("git"):
        r2 = subprocess.run(["git", "apply", "-p%d" % level, "--whitespace=nowarn",
                             "--unsafe-paths", "--directory=.", patch_file],
                            cwd=work_dir, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
        if r2.returncode == 0:
            log("applied with git apply")
            return
        out += "\n" + r2.stdout.decode("utf-8", "replace")
    die("patch %s failed:\n%s" % (patch_file, out))


# ----------------------------------------------------------------------------
# prefix snapshots / packaging
# ----------------------------------------------------------------------------

def walk_prefix(prefix):
    out = []
    for root, dirs, files in os.walk(prefix):
        rel_root = os.path.relpath(root, prefix)
        keep = []
        for d in dirs:
            full = os.path.join(root, d)
            if os.path.islink(full):
                files.append(d)
            else:
                keep.append(d)
        dirs[:] = keep
        for f in files:
            rel = f if rel_root == "." else os.path.join(rel_root, f)
            out.append(rel)
        if not files and not keep and rel_root != ".":
            pass
    return sorted(out)


def cmd_snapshot(a):
    prefix, out = a
    files = walk_prefix(prefix) if os.path.isdir(prefix) else []
    with open(out, "w") as f:
        f.write("\n".join(files) + ("\n" if files else ""))


_glob_cache = {}


def glob_to_regex(pat):
    """globset semantics (literal_separator = false, so '*' also matches '/'),
    with {a,b} alternatives and '**'."""
    if pat in _glob_cache:
        return _glob_cache[pat]
    i, n = 0, len(pat)
    out = ""
    depth = 0
    while i < n:
        c = pat[i]
        if c == "*":
            if i + 1 < n and pat[i + 1] == "*":
                # '**/' -> any number of dirs, '/**' -> anything below
                if i + 2 < n and pat[i + 2] == "/":
                    out += "(?:.*/)?"
                    i += 3
                    continue
                out += ".*"
                i += 2
                continue
            out += ".*"
        elif c == "?":
            out += "."
        elif c == "[":
            j = pat.find("]", i + 1)
            if j == -1:
                out += re.escape(c)
            else:
                body = pat[i + 1:j]
                if body.startswith("!"):
                    body = "^" + body[1:]
                out += "[" + body + "]"
                i = j
        elif c == "{":
            depth += 1
            out += "(?:"
        elif c == "}" and depth:
            depth -= 1
            out += ")"
        elif c == "," and depth:
            out += "|"
        else:
            out += re.escape(c)
        i += 1
    rx = re.compile("^" + out + "$")
    _glob_cache[pat] = rx
    return rx


def files_glob(pat):
    """rattler-build GlobVec: 'dir/' matches below, otherwise file or folder."""
    p = pat[2:] if pat.startswith("./") else pat
    if p in ("", "."):
        return glob_to_regex("**")
    if p.endswith("/"):
        return glob_to_regex(p + "**")
    return glob_to_regex(p + "{,/**}")


def _is_text(data):
    return b"\x00" not in data[:65536] and b"\x00" not in data[-65536:]


def cmd_collect(a):
    # collect prefix snapshot_before dest_files_dir info_dir placeholder spec_json
    prefix, before_file, dest, info_dir, placeholder, spec_file = a
    spec = json.load(open(spec_file))
    before = set(l for l in open(before_file).read().splitlines() if l) if before_file else set()
    current = walk_prefix(prefix)
    new = [p for p in current if p not in before]
    inc = [files_glob(g) for g in spec.get("include", [])]
    exc = [files_glob(g) for g in spec.get("exclude", [])]
    always = [files_glob(g) for g in spec.get("always_include", [])]
    selected = []
    for p in new:
        if p.endswith((".pyc",)) and "__pycache__" in p and spec.get("drop_pycache", True):
            continue
        if inc and not any(r.match(p) for r in inc):
            continue
        if exc and any(r.match(p) for r in exc):
            continue
        selected.append(p)
    if always:
        for p in current:
            if p not in selected and any(r.match(p) for r in always):
                selected.append(p)
    selected.sort()
    os.makedirs(dest, exist_ok=True)
    os.makedirs(info_dir, exist_ok=True)
    ph = placeholder.encode()
    real_prefix = os.path.realpath(prefix)
    paths = []
    n_bin_prefix = 0
    for rel in selected:
        src = os.path.join(prefix, rel)
        dst = os.path.join(dest, rel)
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        entry = {"_path": rel}
        if os.path.islink(src):
            target = os.readlink(src)
            if os.path.isabs(target):
                for base in (prefix, real_prefix):
                    if target == base or target.startswith(base + "/"):
                        target = os.path.relpath(target, os.path.dirname(os.path.join(base, rel)))
                        break
            if os.path.lexists(dst):
                os.unlink(dst)
            os.symlink(target, dst)
            entry["path_type"] = "softlink"
            paths.append(entry)
            continue
        if os.path.isdir(src):
            os.makedirs(dst, exist_ok=True)
            entry["path_type"] = "directory"
            paths.append(entry)
            continue
        with open(src, "rb") as f:
            data = f.read()
        has = ph in data if ph else False
        try:
            os.link(src, dst)
        except OSError:
            shutil.copy2(src, dst)
        st = os.stat(src)
        entry.update(path_type="hardlink", sha256=hashlib.sha256(data).hexdigest(),
                     size_in_bytes=len(data))
        if st.st_mode & stat.S_IXUSR:
            entry["_x"] = True
        if has:
            if _is_text(data):
                entry["prefix_placeholder"] = placeholder
                entry["file_mode"] = "text"
            else:
                n_bin_prefix += 1
                entry["_binary_prefix"] = True
        paths.append(entry)
    with open(os.path.join(info_dir, "files"), "w") as f:
        f.write("\n".join(selected) + ("\n" if selected else ""))
    with open(os.path.join(info_dir, "paths.json"), "w") as f:
        json.dump({"paths": paths, "paths_version": 1}, f, indent=1)
    if n_bin_prefix:
        log("note: %d binary file(s) embed the build prefix (not relocated)" % n_bin_prefix)
    log("packaged %d files" % len(selected))
    print(len(selected))


def _relocate_bytes(data, old, new):
    return data.replace(old.encode(), new.encode())


def cmd_install(a):
    # install pkg_dir prefix mode(copy|link) [name]
    pkg_dir, prefix, mode = a[:3]
    info = os.path.join(pkg_dir, "info")
    files_dir = os.path.join(pkg_dir, "files")
    paths = json.load(open(os.path.join(info, "paths.json")))["paths"]
    meta = json.load(open(os.path.join(info, "index.json")))
    os.makedirs(prefix, exist_ok=True)
    installed = []
    for e in paths:
        rel = e["_path"]
        src = os.path.join(files_dir, rel)
        dst = os.path.join(prefix, rel)
        parent = os.path.dirname(dst)
        if os.path.islink(parent) or (os.path.exists(parent) and not os.path.isdir(parent)):
            pass
        os.makedirs(parent, exist_ok=True)
        if os.path.lexists(dst) and not (os.path.isdir(dst) and not os.path.islink(dst)):
            os.unlink(dst)
        t = e.get("path_type")
        if t == "softlink":
            os.symlink(os.readlink(src), dst)
        elif t == "directory":
            os.makedirs(dst, exist_ok=True)
        elif e.get("prefix_placeholder"):
            with open(src, "rb") as f:
                data = f.read()
            data = _relocate_bytes(data, e["prefix_placeholder"], prefix)
            with open(dst, "wb") as f:
                f.write(data)
            shutil.copymode(src, dst)
        else:
            if os.path.isdir(dst) and not os.path.islink(dst):
                shutil.rmtree(dst)
            if mode == "link":
                try:
                    os.link(src, dst)
                except OSError:
                    shutil.copy2(src, dst)
            else:
                shutil.copy2(src, dst)
        installed.append(rel)
    cm = os.path.join(prefix, "conda-meta")
    os.makedirs(cm, exist_ok=True)
    rec = dict(meta)
    rec["files"] = installed
    rec["ef_package_dir"] = pkg_dir
    with open(os.path.join(cm, "%s-%s-%s.json" % (meta["name"], meta["version"], meta["build"])), "w") as f:
        json.dump(rec, f, indent=1)


def cmd_subst(a):
    # subst in out : replace @@EF:VAR@@ with os.environ[VAR]
    src, dst = a
    text = open(src, encoding="utf-8", errors="surrogateescape").read()
    text = text.replace("\r\n", "\n")

    def rep(m):
        return os.environ.get(m.group(1), "")
    text = re.sub(r"@@EF:([A-Za-z_][A-Za-z0-9_]*)@@", rep, text)
    with open(dst, "w", encoding="utf-8", errors="surrogateescape") as f:
        f.write(text)


