def _section(spec, key):
    v = spec.get(key)
    if v is None:
        return [], []
    if isinstance(v, dict):
        return list(v.get("exists") or []), list(v.get("not_exists") or [])
    if isinstance(v, str):
        return [v], []
    return list(v), []


def cmd_test_contents(a):
    pkg_dir, spec_file, platform, noarch = a
    spec = json.load(open(spec_file))
    files = [l for l in open(os.path.join(pkg_dir, "info", "files")).read().splitlines() if l]
    issues = []

    def rx(p):
        return glob_to_regex(p)

    def check(globs_sets, label, exists):
        for raw, rxs in globs_sets:
            hits = [f for f in files if any(r.match(f) for r in rxs)]
            if exists and not hits:
                issues.append("no match for %s glob: %s" % (label, raw))
            if not exists and hits:
                issues.append("%s 'not_exists' glob %s matched %s" % (label, raw, hits[:3]))

    for exists_flag, idx in ((True, 0), (False, 1)):
        inc = _section(spec, "include")[idx]
        check([(g, [rx("include/" + g)]) for g in inc], "include", exists_flag)
        b = _section(spec, "bin")[idx]
        if platform == "emscripten-wasm32":
            # rattler-build looks for bin/<name>.js and bin/<name>.wasm; the
            # exact name is accepted too (older recipes list "foo.wasm")
            check([(g, [rx("bin/%s.js" % g), rx("bin/%s.wasm" % g), rx("bin/" + g)]) for g in b],
                  "bin", exists_flag)
        else:
            check([(g, [rx("bin/" + g)]) for g in b], "bin", exists_flag)
        lb = _section(spec, "lib")[idx]
        sets = []
        for g in lb:
            if platform.startswith("osx"):
                if g.endswith((".dylib", ".a")):
                    sets.append((g, [rx("lib/" + g)]))
                else:
                    sets.append((g, [rx("lib/{,lib}%s.dylib" % g), rx("lib/{,lib}%s.*.dylib" % g)]))
            else:
                if g.endswith((".so", ".a")) or ".so." in g:
                    sets.append((g, [rx("lib/" + g)]))
                else:
                    sets.append((g, [rx("lib/{,lib}%s.so" % g), rx("lib/{,lib}%s.so.*" % g)]))
        check(sets, "lib", exists_flag)
        sp = _section(spec, "site_packages")[idx]
        base = "site-packages" if noarch == "python" else "lib/python*/site-packages"
        sets = []
        for g in sp:
            if "/" in g:
                sets.append((g, [rx("%s/%s" % (base, g))]))
            else:
                parts = g.split(".")
                last = parts.pop()
                path = "/".join(parts) + ("/" if parts else "")
                sets.append((g, [rx("%s/%s%s.py" % (base, path, last)),
                                 rx("%s/%s%s/__init__.py" % (base, path, last))]))
        check(sets, "site_packages", exists_flag)
        fl = _section(spec, "files")[idx]
        check([(g, [rx(g)]) for g in fl], "files", exists_flag)
    if spec.get("strict"):
        log("note: strict package_contents mode is not enforced")
    if issues:
        for i in issues:
            log("  FAIL %s" % i)
        die("package_contents test failed")
    log("package_contents test passed")


